// Eladamri, Lord of Leaves
// status: ready
// Other Elf creatures have forestwalk. (They can't be blocked as long as defending player controls a Forest.)
// Other Elves have shroud. (They can't be the targets of spells or abilities.)
#[allow(unused_imports)] use cantrip_api::*;
#[allow(unused_variables)] fn ability_0_affects(q: &dyn LayerQuery, source: ObjectId, affected: ObjectId, so_far: &Chars) -> bool { let asker = &Asker::new(source, q.controller(source)); (!(Some(asker.source) == Some(affected)) && ((*so_far).has_subtype(q.words(asker.source).subtype(Subtype::Elf)) && (*so_far).is(CardType::Creature))) }
#[allow(unused_variables)] fn ability_0_apply_0(q: &dyn LayerQuery, source: ObjectId, chars: &mut Chars) { let asker = &Asker::new(source, q.controller(source)); if let Some(walk) = Keyword::landwalk(q.words(source).subtype(Subtype::Forest)) { chars.keywords = chars.keywords.with(walk); } }
#[allow(unused_variables)] fn ability_1_affects(q: &dyn LayerQuery, source: ObjectId, affected: ObjectId, so_far: &Chars) -> bool { let asker = &Asker::new(source, q.controller(source)); (!(Some(asker.source) == Some(affected)) && (*so_far).has_subtype(q.words(asker.source).subtype(Subtype::Elf))) }
#[allow(unused_variables)] fn ability_1_apply_0(q: &dyn LayerQuery, source: ObjectId, chars: &mut Chars) { let asker = &Asker::new(source, q.controller(source)); chars.keywords = chars.keywords.with(Keyword::Shroud); }

